// Recipients come from profiles (the Recipients node), never a hardcoded
// personal address: the mail follows whoever holds the role today, and a
// deactivated account (profiles.deactivated_at, migration 032) stops getting
// it. The company inbox is used only when nobody qualifies.
const FALLBACK_TO = 'nixgensolutions@gmail.com';
const EMAIL_RE = /^[^\s@,;<>"']+@[^\s@,;<>"']+\.[^\s@,;<>"']+$/;
const people = $('Recipients').all().map(i => i.json).flat()
  .filter(p => p && p.id && !p.deactivated_at && EMAIL_RE.test(String(p.email || '').trim()));
const can = (p, feature, level) => p.role === 'admin'
  || (p.permissions || {})[feature] === 'edit'
  || (level === 'view' && (p.permissions || {})[feature] === 'view');
const addressOf = (list) => [...new Set(list.map(p => String(p.email).trim().toLowerCase()))].join(',');
const TO = addressOf(people.filter(p => p.role === 'admin')) || FALLBACK_TO;

const rows = $input.all().map(i => i.json).flat()
  .filter(x => x && typeof x === 'object' && Object.keys(x).length > 0);
const MNL = 'Asia/Manila';
const dkey = (d) => new Intl.DateTimeFormat('en-CA',{timeZone:MNL,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(d));
const today = dkey(new Date());
const peso = n => '₱' + Number(n||0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
const wrap = (title, sub, body) => `<div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#111">
  <h2 style="margin:0 0 4px">${title}</h2><p style="margin:0 0 16px;color:#666">${sub}</p>${body}
  <p style="margin-top:20px;color:#999;font-size:12px">Sent by n8n</p></div>`;
const table = (headers, trs) => `<table style="border-collapse:collapse;font-size:14px">
  <tr style="text-align:left;color:#666;font-size:12px;text-transform:uppercase">${headers.map(h=>`<th style="padding:6px 12px">${h}</th>`).join('')}</tr>
  ${trs}</table>`;
// Cell values are DB text (task titles, client names) members edit: always escaped.
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const td = (v, extra='') => `<td style="padding:6px 12px;border-bottom:1px solid #eee;${extra}">${esc(v)}</td>`;

const od = rows.filter(t => t.due_date && t.status !== 'done' && dkey(t.due_date) < today);
const trs = od.map(t => `<tr>${td(t.title)}${td(t.clients?.name||'—')}${td(t.priority||'—')}${td(t.due_date,'color:#b91c1c;font-family:monospace')}</tr>`).join('')
  || `<tr>${td('Nothing overdue 🎉','color:#999')}${td('')}${td('')}${td('')}</tr>`;
// Fetch caps at 300 rows; say so rather than under-report silently.
const html = wrap('DeskDev — Overdue tasks', `${od.length >= 300 ? '300+' : od.length} task(s) past due`, table(['Task','Client','Priority','Due'], trs));
const __n = od.length; return (false && !__n) ? [] : [{ json: { html, count: __n, to: TO } }];
